import { MakeLogicType, afterMount, connect, kea, path } from 'kea'
import { loaders } from 'kea-loaders'

import { teamLogic } from 'scenes/teamLogic'

import { visionScannersList } from 'products/replay_vision/frontend/generated/api'
import { type ReplayScannerApi, ScannerTypeEnumApi } from 'products/replay_vision/frontend/generated/api.schemas'

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface scannerPickerLogicValues {
    currentTeamId: number | null // teamLogic
    scanners: ReplayScannerApi[]
    scannersLoading: boolean
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface scannerPickerLogicActions {
    loadScanners: (_: void) => void
    loadScannersFailure: (
        error: string,
        errorObject?: any
    ) => {
        error: string
        errorObject?: any
    }
    loadScannersSuccess: (
        scanners: ReplayScannerApi[],
        payload?: void
    ) => {
        scanners: ReplayScannerApi[]
        payload?: void
    }
}

export type scannerPickerLogicType = MakeLogicType<scannerPickerLogicValues, scannerPickerLogicActions>

// A team's saved scanners usually fit in one page; the loader still follows `next` for the rest.
const SCANNER_PAGE_SIZE = 500

export const scannerPickerLogic = kea<scannerPickerLogicType>([
    path(['products', 'replay_vision', 'frontend', 'components', 'ScannerPicker', 'scannerPickerLogic']),
    connect(() => ({
        values: [teamLogic, ['currentTeamId']],
    })),
    loaders(({ values }) => ({
        scanners: [
            [] as ReplayScannerApi[],
            {
                loadScanners: async (_: void, breakpoint): Promise<ReplayScannerApi[]> => {
                    if (!values.currentTeamId) {
                        return []
                    }
                    const scanners: ReplayScannerApi[] = []
                    for (let offset = 0; ; offset += SCANNER_PAGE_SIZE) {
                        const page = await visionScannersList(String(values.currentTeamId), {
                            limit: SCANNER_PAGE_SIZE,
                            offset,
                        })
                        // Stops paging once the picker unmounts or a newer load starts.
                        breakpoint()
                        // The workflow step refuses experiment scanners, so they aren't offered.
                        scanners.push(
                            ...page.results.filter((scanner) => scanner.scanner_type !== ScannerTypeEnumApi.Experiment)
                        )
                        if (!page.next || page.results.length === 0) {
                            return scanners
                        }
                    }
                },
            },
        ],
    })),
    afterMount(({ actions }) => {
        actions.loadScanners()
    }),
])
